import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"17、【随】 震下兑上","description":"横渠易说 - 17、【随】 震下兑上","frontmatter":{"title":"17、【随】 震下兑上","description":"横渠易说 - 17、【随】 震下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/019.md","filePath":"zh/classics/hengqu/019.md"}'),l={name:"zh/classics/hengqu/019.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_17、【随】-震下兑上" tabindex="-1">17、【随】 震下兑上 <a class="header-anchor" href="#_17、【随】-震下兑上" aria-label="Permalink to “17、【随】 震下兑上”">​</a></h1><h3 id="彖曰-随-刚来而下柔-动而说-随。大亨贞无咎而天下随时-随时之义大矣哉" tabindex="-1">彖曰：随，刚来而下柔，动而说，随。大亨贞无咎而天下随时，随时之义大矣哉! <a class="header-anchor" href="#彖曰-随-刚来而下柔-动而说-随。大亨贞无咎而天下随时-随时之义大矣哉" aria-label="Permalink to “彖曰：随，刚来而下柔，动而说，随。大亨贞无咎而天下随时，随时之义大矣哉!”">​</a></h3><h3 id="象曰-泽中有雷-随-君子以向晦入宴息。" tabindex="-1">象曰：泽中有雷，随，君子以向晦入宴息。 <a class="header-anchor" href="#象曰-泽中有雷-随-君子以向晦入宴息。" aria-label="Permalink to “象曰：泽中有雷，随，君子以向晦入宴息。”">​</a></h3><h3 id="上九-下居于初也-故曰-刚来下柔-。" tabindex="-1">上九，下居于初也，故曰“刚来下柔”。 <a class="header-anchor" href="#上九-下居于初也-故曰-刚来下柔-。" aria-label="Permalink to “上九，下居于初也，故曰“刚来下柔”。”">​</a></h3><h3 id="初九-官有渝-贞吉-出门交有功。-象曰-官有渝-从正吉也。-出门交有功-不失也。" tabindex="-1">初九，官有渝，贞吉，出门交有功。 象曰：“官有渝”，从正吉也。“出门交有功”，不失也。 <a class="header-anchor" href="#初九-官有渝-贞吉-出门交有功。-象曰-官有渝-从正吉也。-出门交有功-不失也。" aria-label="Permalink to “初九，官有渝，贞吉，出门交有功。 象曰：“官有渝”，从正吉也。“出门交有功”，不失也。”">​</a></h3><p>言凡所治务能变而任正，不胶柱也。处随之初，为动之主，心无私系，故能动必择义，善与人同者也。</p><h3 id="六二-系小子-失丈夫。-象曰-系小子-弗兼与也。" tabindex="-1">六二，系小子，失丈夫。 象曰：“系小子”，弗兼与也。 <a class="header-anchor" href="#六二-系小子-失丈夫。-象曰-系小子-弗兼与也。" aria-label="Permalink to “六二，系小子，失丈夫。 象曰：“系小子”，弗兼与也。”">​</a></h3><h3 id="六三-系丈夫-失小子。随有求得-利居贞。-象曰-系丈夫-志舍下也。" tabindex="-1">六三，系丈夫，失小子。随有求得，利居贞。 象曰：“系丈夫”，志舍下也。 <a class="header-anchor" href="#六三-系丈夫-失小子。随有求得-利居贞。-象曰-系丈夫-志舍下也。" aria-label="Permalink to “六三，系丈夫，失小子。随有求得，利居贞。 象曰：“系丈夫”，志舍下也。”">​</a></h3><p>舍小随大，所求可得，必守正不邪乃吉。</p><h3 id="九四-随有获-贞凶。有孚在道-以明何咎-象曰-随有获-其义凶也。-有孚在道-明功也。" tabindex="-1">九四，随有获，贞凶。有孚在道，以明何咎! 象曰：“随有获”，其义凶也。“有孚在道”，明功也。 <a class="header-anchor" href="#九四-随有获-贞凶。有孚在道-以明何咎-象曰-随有获-其义凶也。-有孚在道-明功也。" aria-label="Permalink to “九四，随有获，贞凶。有孚在道，以明何咎! 象曰：“随有获”，其义凶也。“有孚在道”，明功也。”">​</a></h3><p>以阳居阴，利于比三则凶也。处随之世，为众所附，苟利其获，凶之道也。能以信存道，则功业可明，无所咎矣。</p><h3 id="九五-孚于嘉-吉。-象曰-孚于嘉吉-位正中也。" tabindex="-1">九五，孚于嘉，吉。 象曰：“孚于嘉吉”，位正中也。 <a class="header-anchor" href="#九五-孚于嘉-吉。-象曰-孚于嘉吉-位正中也。" aria-label="Permalink to “九五，孚于嘉，吉。 象曰：“孚于嘉吉”，位正中也。”">​</a></h3><h3 id="上六-拘系之-乃从维之-王用亨于西山。-象曰-拘系之-上穷也。" tabindex="-1">上六，拘系之，乃从维之，王用亨于西山。 象曰：“拘系之”，上穷也。 <a class="header-anchor" href="#上六-拘系之-乃从维之-王用亨于西山。-象曰-拘系之-上穷也。" aria-label="Permalink to “上六，拘系之，乃从维之，王用亨于西山。 象曰：“拘系之”，上穷也。”">​</a></h3><p>处随之世而刚正宅尊，善为众信，故吉。或曰：孚于二则吉。</p>',14)])])}const p=e(l,[["render",t]]);export{b as __pageData,p as default};
